def {{fn_name}}(text, pattern, base=257, mod=10**9+7):
    n, m = len(text), len(pattern)
    if m > n: return -1
    ph = 0; th = 0; pw = 1
    for i in range(m):
        ph = (ph*base + ord(pattern[i])) % mod
        th = (th*base + ord(text[i])) % mod
        if i < m-1: pw = (pw*base) % mod
    for i in range(n - m + 1):
        if ph == th and text[i:i+m] == pattern:
            return i
        if i < n - m:
            th = ((th - ord(text[i])*pw) * base + ord(text[i+m])) % mod
    return -1
